// FLAME EVIDENCE LAB — model registry and guarded scorers
// Models are honest artifacts: verified reproductions from recovered NASA data
// (FLEX v2), spec-preserved coefficients validated on recovered data (CFI-G),
// and a preserved negative result (SPICE). No model is a flight-qualified
// safety device; guards refuse out-of-domain inputs.

import flexCard from "@/data/../../models/flex-extinction/v2/model_card.json";

export interface ModelCard {
  /** Cards are generated by scripts/verify_flex_model.py with the field model_id. */
  model_id: string;
  task: string;
  pillar: string;
  status: "verified-reproduction" | "exploratory" | "negative-result" | "absent";
  statusDetail: string;
  data: {
    source: string;
    rowsRaw?: number;
    rowsClean?: number;
    rowsUsed?: number;
    positives?: number;
    negatives?: number;
    extinction?: number;
    extinctionShare?: number;
    features: string[];
    excludedAsLeakage?: string[];
    outcomeDefinition?: string;
  };
  validation: string;
  metrics: Record<string, unknown>;
  historicalRecorded?: Record<string, unknown>;
  limitations: string[];
  trainedAt: string;
  framework: string;
  domainGuard?: Record<string, unknown>;
}

// ---- FLEX v2 (retrained from recovered data; card generated by scripts/verify_flex_model.py) ----
const flex = flexCard as unknown as ModelCard;

export function getFlexCard(): ModelCard {
  return flex;
}

const flexScoring = (flexCard as { inBrowserScoring: { featureNames: string[]; means: number[]; stds: number[]; coefStandardized: number[] } }).inBrowserScoring;

export interface FlexInputs {
  xo2: number; // ambient O2 mole fraction
  pressureMmHg: number;
  d0Mm: number; // initial droplet diameter
  fuel: "Methanol" | "Heptane";
  heFraction?: number; // ambient He mole fraction (0 if absent)
  coFraction?: number; // ambient CO mole fraction (0 if absent)
  gravityG?: number; // local gravity in g
}

export interface FlexPrediction {
  ok: boolean;
  refusal?: string;
  score?: number; // uncalibrated relative score
  interpretation?: string;
  applicability: { inDomain: boolean; violations: string[] };
  provenance: string;
}

export function runFlexModel(inputs: FlexInputs): FlexPrediction {
  const violations: string[] = [];
  const g = inputs.gravityG ?? 1e-6;
  if (g > 0.02) violations.push(`Gravity ${g} g exceeds the verified microgravity domain (max 0.02 g).`);
  if (inputs.fuel !== "Methanol" && inputs.fuel !== "Heptane") violations.push(`Fuel '${inputs.fuel}' is outside the FLEX domain (Methanol/Heptane only).`);
  if (inputs.xo2 < 0.15 || inputs.xo2 > 0.7) violations.push(`O2 fraction ${inputs.xo2} outside observed range 0.15-0.70.`);
  if (inputs.pressureMmHg < 400 || inputs.pressureMmHg > 1150) violations.push(`Pressure ${inputs.pressureMmHg} mmHg outside observed range 400-1150.`);
  if (inputs.d0Mm < 1.0 || inputs.d0Mm > 5.0) violations.push(`Droplet diameter ${inputs.d0Mm} mm outside observed range 1.0-5.0.`);
  const inDomain = violations.length === 0;
  if (!inDomain) {
    return {
      ok: false,
      refusal: "The FLEX model refuses this prediction: " + violations.join(" ") + " Microgravity ISS data are not a validated basis for this case (no partial-gravity or 1-g validation exists).",
      applicability: { inDomain: false, violations },
      provenance: "FLEX extinction model v2 — domain guard",
    };
  }
  const x = [
    inputs.xo2,
    inputs.pressureMmHg,
    inputs.d0Mm,
    inputs.fuel === "Heptane" ? 1 : 0,
    inputs.heFraction ?? 0,
    inputs.coFraction ?? 0,
  ];
  const z = x.map((v, i) => (v - flexScoring.means[i]) / flexScoring.stds[i]);
  const lin = flexScoring.coefStandardized.reduce((acc, c, i) => acc + c * z[i], 0);
  const score = 1 / (1 + Math.exp(-lin));
  return {
    ok: true,
    score,
    interpretation: (() => {
      const rv = (flex as { reverification?: { championGroupBootstrapCi?: { ci95?: [number, number]; method?: string } } }).reverification;
      const ci = rv?.championGroupBootstrapCi?.ci95;
      const ciTxt = ci ? ` Out-of-fold AUC with group-bootstrap 95% CI [${ci[0].toFixed(3)}, ${ci[1].toFixed(3)}] (stratified group CV; groups atomic).` : "";
      return `Relative extinction score ${score.toFixed(3)} (uncalibrated). Trained on visible-flame extinction outcomes of 262 FLEX microgravity tests (grouped AUC ${(flex.metrics.groupedAucMean as number).toFixed(3)}).${ciTxt} This is NOT a calibrated probability and NOT a flammability or cabin-safety verdict.`;
    })(),
    applicability: { inDomain: true, violations: [] },
    provenance: "FLEX extinction model v2 — IRLS logistic, GroupKFold-4 by condition; card models/flex-extinction/v2/",
  };
}

// ---- CFI-G hot ignition (spec-preserved coefficients, validated on recovered data) ----
const cfig = {
  featureNames: ["Xf_before", "p_bar", "XO2", "HC_burn_rate", "O2_flow", "Tad_K", "Zst", "fuel_butane", "fuel_ethane", "fuel_propane"],
  coef: [-1.7059, -0.3313, -0.4338, -0.0445, -0.1823, 1.7687, -0.2663, -0.1297, 0.1397, -0.0023],
  intercept: 1.0748,
  means: [0.15088, 1.76332, 0.60705, 1.37521, 4.99826, 2431.67875, 0.46864, 0.39726, 0.30822, 0.29452],
  stds: [0.09904, 1.05367, 0.27788, 0.65783, 2.3841, 327.10888, 0.1885, 0.48933, 0.46176, 0.45583],
};

export interface CfigInputs {
  xfBefore: number; // fuel mole fraction before test
  pBar: number; // pressure bar
  xo2: number;
  hcBurnRate: number; // mg/s
  o2Flow: number; // mg/s
  tadK: number; // adiabatic flame temp K
  zst: number; // stoichiometric mixture fraction
  fuel: "butane" | "ethane" | "propane";
  gravityG?: number;
}

export function runCfigModel(inputs: CfigInputs): FlexPrediction {
  const violations: string[] = [];
  const g = inputs.gravityG ?? 1e-6;
  if (g > 0.02) violations.push("CFI-G data are ISS microgravity tests only.");
  if (inputs.xo2 < 0.15 || inputs.xo2 > 0.5) violations.push(`O2 ${inputs.xo2} outside observed 0.15-0.5.`);
  if (inputs.pBar < 0.8 || inputs.pBar > 3) violations.push(`Pressure ${inputs.pBar} bar outside observed ~1 bar regime.`);
  if (violations.length) {
    return {
      ok: false,
      refusal: "The CFI-G scorer refuses this input: " + violations.join(" "),
      applicability: { inDomain: false, violations },
      provenance: "CFI-G hot ignition model — domain guard",
    };
  }
  const fuels: Record<string, number[]> = {
    butane: [1, 0, 0],
    ethane: [0, 1, 0],
    propane: [0, 0, 1],
  };
  const f = fuels[inputs.fuel];
  const x = [inputs.xfBefore, inputs.pBar, inputs.xo2, inputs.hcBurnRate, inputs.o2Flow, inputs.tadK, inputs.zst, ...f];
  const z = x.map((v, i) => (v - cfig.means[i]) / cfig.stds[i]);
  const lin = cfig.intercept + cfig.coef.reduce((acc, c, i) => acc + c * z[i], 0);
  const score = 1 / (1 + Math.exp(-lin));
  return {
    ok: true,
    score,
    interpretation: `Exploratory score ${score.toFixed(3)}. IMPORTANT: this model does NOT outperform a single-feature oxygen baseline under grouped validation (recorded AUC 0.682 vs 0.728) and is retained as an honest negative/exploratory result. Do not use for decisions.`,
    applicability: { inDomain: true, violations: [] },
    provenance: "CFI-G hot ignition — spec-preserved logistic coefficients validated on recovered PSI-159 inverse table (146 rows/131 positives, exact match)",
  };
}

